<?php

namespace App\Support;

use Illuminate\Http\UploadedFile;
use RuntimeException;

/**
 * LV-S10 (audit, 6 Nov 2026): one check for uploaded files.
 *  - The type is read from the file's content (finfo), not from the name the client sent.
 *  - Only listed types pass; the stored extension comes from the detected type, never the client.
 *  - Script and markup types (php, phtml, phar, html, svg with script, js, exe ...) are refused
 *    whatever their name, and so is any file whose name hides a second script extension.
 *  - Size is capped. Stored names are generated by the server.
 */
class SafeUpload
{
    /** detected MIME => stored extension */
    public const TYPES = [
        'image/jpeg' => 'jpg', 'image/pjpeg' => 'jpg', 'image/png' => 'png', 'image/webp' => 'webp',
        'image/heic' => 'heic', 'image/heif' => 'heic', 'image/gif' => 'gif',
        'application/pdf' => 'pdf',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' => 'xlsx',
        'application/vnd.ms-excel' => 'xls', 'application/msexcel' => 'xls', 'application/x-msexcel' => 'xls',
        'text/csv' => 'csv', 'text/plain' => 'csv', 'application/csv' => 'csv',
        'application/zip' => 'xlsx',   // xlsx is a zip; only accepted where 'xlsx' is allowed (checked below)
    ];

    private const BLOCKED_NAME = '/\.(php\d?|phtml|phar|phps|pht|cgi|pl|py|sh|asp|aspx|jsp|js|mjs|html?|svg|xml|exe|bat|cmd|htaccess)(\.|$)/i';

    /**
     * @param string[] $allowed stored extensions this upload may have, e.g. ['jpg','png','pdf']
     * @return string the safe extension to store with
     */
    public static function check(UploadedFile $file, array $allowed, int $maxKb = 10240): string
    {
        if (! $file->isValid()) {
            throw new RuntimeException('Upload failed.');
        }
        if ($file->getSize() > $maxKb * 1024) {
            throw new RuntimeException('File is larger than '.round($maxKb / 1024, 1).' MB.');
        }
        if (preg_match(self::BLOCKED_NAME, (string) $file->getClientOriginalName())) {
            throw new RuntimeException('This file type is not allowed.');
        }
        $mime = self::detect($file->getRealPath());
        $ext = self::TYPES[$mime] ?? null;
        if ($mime === 'application/zip' && ! in_array('xlsx', $allowed, true)) {
            $ext = null;
        }
        if ($ext === 'csv' && ! in_array('csv', $allowed, true)) {
            $ext = null;
        }
        if ($ext === null || ! in_array($ext, $allowed, true)) {
            throw new RuntimeException('This file type is not allowed ('.$mime.').');
        }
        if (in_array($ext, ['csv'], true) && self::looksLikeScript($file->getRealPath())) {
            throw new RuntimeException('This file type is not allowed.');
        }

        return $ext;
    }

    /** True for names that end in, or hide, a script / markup extension (e.g. bill.php, bill.php.jpg). */
    public static function isBlockedName(string $name): bool
    {
        return (bool) preg_match(self::BLOCKED_NAME, $name);
    }

    /** Server-generated file name: <prefix>_<date>_<random>.<ext> */
    public static function name(string $prefix, string $ext): string
    {
        $prefix = preg_replace('/[^A-Za-z0-9_-]/', '', $prefix) ?: 'file';

        return $prefix.'_'.date('Ymd_His').'_'.bin2hex(random_bytes(4)).'.'.$ext;
    }

    public static function detect(string $path): string
    {
        $f = new \finfo(FILEINFO_MIME_TYPE);

        return (string) $f->file($path);
    }

    private static function looksLikeScript(string $path): bool
    {
        $head = (string) @file_get_contents($path, false, null, 0, 4096);

        return (bool) preg_match('/<\?php|<script|<\?=/i', $head);
    }
}
